<script>(()=>{const modal=document.getElementById('receipt-confirm-modal');if(!modal)return;let pendingForm=null;const close=()=>{modal.classList.remove('is-open');modal.setAttribute('aria-hidden','true');pendingForm=null};document.querySelectorAll('form[data-receipt-confirm-form]').forEach(form=>form.addEventListener('submit',event=>{event.preventDefault();pendingForm=form;document.getElementById('receipt-confirm-message').textContent=`Confirme uniquement lorsque le reçu de ${form.dataset.requesterName} t’a bien été remis.`;modal.classList.add('is-open');modal.setAttribute('aria-hidden','false');modal.querySelector('.receipt-confirm-cancel').focus()}));modal.querySelectorAll('[data-receipt-confirm-close]').forEach(button=>button.addEventListener('click',close));document.getElementById('receipt-confirm-submit').addEventListener('click',()=>{if(!pendingForm)return;const form=pendingForm;pendingForm=null;HTMLFormElement.prototype.submit.call(form)});document.addEventListener('keydown',event=>{if(event.key==='Escape'&&modal.classList.contains('is-open'))close()})})();</script>
